const gridContainer = document.getElementById("sudoku-grid");
const statusMsg = document.getElementById("status-message");

// Hold the C++ WebAssembly module reference
let sudokuModule = null;

// Initialize WebAssembly Module generated by Emscripten
createSudokuModule().then(module => {
  sudokuModule = module;
  statusMsg.textContent = "C++ Solver engine loaded and ready.";
  statusMsg.style.color = "#16a34a";
}).catch(err => {
  statusMsg.textContent = "Failed to load WebAssembly module.";
  statusMsg.style.color = "#dc2626";
  console.error(err);
});

// 1. Build the 9x9 grid in the DOM
function createGrid() {
  gridContainer.innerHTML = "";
  for (let i = 0; i < 81; i++) {
    const input = document.createElement("input");
    input.type = "text";
    input.maxLength = 1;
    input.classList.add("cell");
    input.dataset.index = i;

    input.addEventListener("input", handleInput);
    input.addEventListener("keydown", handleKeyNavigation);

    gridContainer.appendChild(input);
  }
}

// 2. Validate input: allow only digits 1 to 9
function handleInput(e) {
  const value = e.target.value;
  if (!/^[1-9]$/.test(value)) {
    e.target.value = "";
  } else {
    e.target.classList.remove("solved");
    e.target.classList.add("given");
  }
}

// 3. Arrow key navigation between cells
function handleKeyNavigation(e) {
  const currentIndex = parseInt(e.target.dataset.index, 10);
  const row = Math.floor(currentIndex / 9);
  const col = currentIndex % 9;
  let targetIndex = null;

  switch (e.key) {
    case "ArrowUp": if (row > 0) targetIndex = currentIndex - 9; break;
    case "ArrowDown": if (row < 8) targetIndex = currentIndex + 9; break;
    case "ArrowLeft": if (col > 0) targetIndex = currentIndex - 1; break;
    case "ArrowRight": if (col < 8) targetIndex = currentIndex + 1; break;
    case "Backspace": e.target.value = ""; break;
  }

  if (targetIndex !== null) {
    e.preventDefault();
    gridContainer.children[targetIndex]?.focus();
  }
}

// 4. Convert grid inputs to an 81-character string
function getBoardString() {
  const cells = gridContainer.querySelectorAll(".cell");
  let result = "";
  cells.forEach(cell => result += (cell.value ? cell.value : "0"));
  return result;
}

// 5. Populate the grid from an 81-character string
function setBoardString(boardStr, markAsGiven = false) {
  const cells = gridContainer.querySelectorAll(".cell");
  for (let i = 0; i < 81 && i < boardStr.length; i++) {
    const val = boardStr[i];
    if (val !== "0") {
      cells[i].value = val;
      cells[i].classList.add(markAsGiven ? "given" : "solved");
    } else {
      cells[i].value = "";
      cells[i].className = "cell";
    }
  }
}

// ==========================================
// Button & Modal Event Listeners
// ==========================================

// Clear Button
document.getElementById("clear-btn").addEventListener("click", () => {
  gridContainer.querySelectorAll(".cell").forEach(cell => {
    cell.value = "";
    cell.className = "cell";
  });
  statusMsg.textContent = "Grid cleared.";
  statusMsg.style.color = "#64748b";
});

// Solve Button -> Calls C++ via WebAssembly
document.getElementById("solve-btn").addEventListener("click", () => {
  if (!sudokuModule) {
    statusMsg.textContent = "Wasm module not ready yet.";
    statusMsg.style.color = "#dc2626";
    return;
  }

  const currentBoard = getBoardString();
  const startTime = performance.now();
  
  const solution = sudokuModule.solvePuzzle(currentBoard);
  const timeTaken = (performance.now() - startTime).toFixed(2);

  if (solution && solution.length === 81) {
    const cells = gridContainer.querySelectorAll(".cell");
    for (let i = 0; i < 81; i++) {
      if (!cells[i].value) {
        cells[i].value = solution[i];
        cells[i].classList.add("solved");
      }
    }
    statusMsg.textContent = `Solved in ${timeTaken} ms by C++ engine!`;
    statusMsg.style.color = "#16a34a";
  } else {
    statusMsg.textContent = "This puzzle is invalid or unsolvable.";
    statusMsg.style.color = "#dc2626";
  }
});

// --- Modal Popup Logic for Puzzle Generator ---
const difficultyModal = document.getElementById("difficulty-modal");
const openGenerateBtn = document.getElementById("open-generate-btn");
const proceedBtn = document.getElementById("proceed-btn");
const cancelBtn = document.getElementById("cancel-btn");

// Open the popup
openGenerateBtn.addEventListener("click", () => {
  difficultyModal.showModal();
});

// Close the popup if canceled
cancelBtn.addEventListener("click", () => {
  difficultyModal.close();
});

// Trigger C++ Generator when "Proceed" is clicked
proceedBtn.addEventListener("click", () => {
  if (!sudokuModule) {
    statusMsg.textContent = "Engine not loaded yet. Please wait.";
    statusMsg.style.color = "#dc2626";
    difficultyModal.close();
    return;
  }

  // Find the selected difficulty from the radio buttons
  const selectedRadio = document.querySelector('input[name="difficulty"]:checked');
  const difficulty = parseInt(selectedRadio.value);

  // Call C++ Generator
  const puzzleString = sudokuModule.generatePuzzle(difficulty);
  
  // Fill the HTML grid with the new puzzle and lock the cells
  setBoardString(puzzleString, true);
  
  // Update status UI
  const diffName = difficulty === 1 ? "Easy" : difficulty === 2 ? "Medium" : "Hard";
  statusMsg.textContent = `Generated new ${diffName} puzzle.`;
  statusMsg.style.color = "#64748b";

  // Close the popup window
  difficultyModal.close();
});

// Initialize grid on page load
createGrid();